import{Z as s,e as t,f as a,a0 as o}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Submission Workflow and Stages Explained","description":"","frontmatter":{},"headers":[],"relativePath":"guides/submissions-workflows/submission-workflow-and-stages-explained.md","filePath":"guides/submissions-workflows/submission-workflow-and-stages-explained.md","lastUpdated":1787061592000}'),n={name:"guides/submissions-workflows/submission-workflow-and-stages-explained.md"};function i(r,e,l,d,u,p){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="submission-workflow-and-stages-explained" tabindex="-1">Submission Workflow and Stages Explained <a class="header-anchor" href="#submission-workflow-and-stages-explained" aria-label="Permalink to &quot;Submission Workflow and Stages Explained&quot;">​</a></h1><p>Formie processes submissions through a staged workflow.</p><p>Instead of treating submission handling as one large save step, Formie moves through a series of smaller stages in order. That lets Formie handle multi-page navigation, draft saving, validation, captcha and spam checks, payment handling, persistence, notifications, integrations, and the final browser response in a predictable way.</p><p>If you are extending submission handling, the workflow tells you where your code belongs. Instead of guessing where custom logic should run, you can choose the stage or task that owns that responsibility.</p><p>That model also explains practical behaviour worth knowing early: why save-and-continue skips spam checks, why integrations wait until after payment succeeds, and why hooking <code>Submission::EVENT_AFTER_SAVE</code> is not always the same as hooking into a front-end submit.</p><p>If you only need custom code on a page submit or when the form is submitted, start with <a href="/guides/submissions-workflows/run-custom-code-on-page-submit-or-form-submit">Run custom code on page submit or form submit</a>. This page is the pipeline itself.</p><p>This guide walks through what runs in each stage, which requests use the full pipeline, and how to choose an extension point. For stage and task names, code examples, and events, see <a href="/developers/submission-workflow">Submission Workflow</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/developers/submission-workflow">Submission Workflow</a> — canonical reference when you start writing code</li><li><a href="/developers/events/submission-events">Submission Events</a></li></ul><h2 id="the-pipeline-at-a-glance" tabindex="-1">The Pipeline at a Glance <a class="header-anchor" href="#the-pipeline-at-a-glance" aria-label="Permalink to &quot;The Pipeline at a Glance&quot;">​</a></h2><p>Each stage contains smaller <strong>tasks</strong> with stable names — useful when you extend the workflow in PHP, but not something you need to memorise to understand the overall flow.</p><p>On a normal front-end submit, Formie moves through eight stages in order:</p><ol><li><strong>Prepare</strong> — set up the request; restore save-and-continue or draft context</li><li><strong>Normalize</strong> — resolve page flow, back navigation, default values</li><li><strong>Validate</strong> — run field and form validation rules</li><li><strong>Screen</strong> — submission guards, captchas, spam keyword and content rules</li><li><strong>Authorize</strong> — stop if earlier errors exist; resolve payment state</li><li><strong>Save</strong> — persist the submission; process payments</li><li><strong>Dispatch</strong> — send notifications; trigger integrations</li><li><strong>Finalize</strong> — build the response; apply next-page or success behaviour</li></ol><p>The order matters. Validation runs before save. Integrations run in <strong>dispatch</strong>, after the submission is stored and payment has had its chance to succeed.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser POST</span></span>
<span class="line"><span>    → prepare (draft context, request init)</span></span>
<span class="line"><span>    → normalize (pages, defaults)</span></span>
<span class="line"><span>    → validate (field rules)</span></span>
<span class="line"><span>    → screen (guards, captcha, spam)</span></span>
<span class="line"><span>    → authorize (errors, payment state)</span></span>
<span class="line"><span>    → save (persist, charge card)</span></span>
<span class="line"><span>    → dispatch (email, CRM, automations)</span></span>
<span class="line"><span>    → finalize (response, replay token)</span></span>
<span class="line"><span>    → Browser response</span></span></code></pre></div><p>Payment provider callbacks re-enter through <strong>payment replay</strong> — a shortened path through save, dispatch, and finalize rather than repeating validation from scratch.</p><h2 id="not-every-request-runs-the-full-pipeline" tabindex="-1">Not Every Request Runs the Full Pipeline <a class="header-anchor" href="#not-every-request-runs-the-full-pipeline" aria-label="Permalink to &quot;Not Every Request Runs the Full Pipeline&quot;">​</a></h2><p>The same form can trigger different workflow <strong>modes</strong>. The mode decides which stages run:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Typical trigger</th><th>What you should expect</th></tr></thead><tbody><tr><td><strong>Submit</strong></td><td>Visitor completes a step or final submit</td><td>Full pipeline — validation, screening, save, dispatch</td></tr><tr><td><strong>Save draft</strong></td><td>Save and continue, or back navigation on a multi-page form</td><td>Persists progress only — no validation, screening, notifications, or integrations</td></tr><tr><td><strong>Edit existing</strong></td><td>Front-end or control panel edit of a saved submission</td><td>Validates and saves; may re-run integrations per form settings; skips notifications and screening</td></tr><tr><td><strong>Payment replay</strong></td><td>Stripe/GoCardless callback or status poll</td><td>Resumes after payment — save, dispatch, finalize</td></tr></tbody></table><p>If you add custom logic to <strong>dispatch</strong>, it will not run when a visitor only saves a draft. That is intentional — drafts are not finished submissions.</p><p>See <a href="/guides/submissions-workflows/save-and-continue-later">Save and continue later</a> for how draft mode fits multi-page forms, and <a href="/guides/submissions-workflows/submission-screening-rules-in-practice">Submission screening rules in practice</a> for what runs during the <strong>screen</strong> stage on a full submit.</p><h2 id="where-your-custom-code-belongs" tabindex="-1">Where Your Custom Code Belongs <a class="header-anchor" href="#where-your-custom-code-belongs" aria-label="Permalink to &quot;Where Your Custom Code Belongs&quot;">​</a></h2><p>You do not always need a custom workflow task. Match the hook to what you actually care about:</p><p><strong>You need to run code after a page submit, or only when the form is submitted</strong> — use <code>EVENT_AFTER_PAGE_ADVANCE</code> / <code>EVENT_AFTER_COMPLETE</code>. See <a href="/guides/submissions-workflows/run-custom-code-on-page-submit-or-form-submit">Run custom code on page submit or form submit</a>. Every page POST uses <code>submit</code> mode; page submit and form submit both post <code>submitAction=submit</code>. Completeness is <code>isIncomplete</code> / next reachable page after page flow, including conditionally hidden last pages.</p><p><strong>You need to react whenever the submission element is saved</strong> — including control panel edits, imports, or API updates — use a submission <strong>element event</strong> such as <code>Submission::EVENT_AFTER_SAVE</code>. That fires on the element, not on the front-end submit request.</p><p><strong>You need logic only during a front-end submit</strong> — for example extra screening before spam checks, or work that should never run on draft saves — listen to <strong>workflow stage or task events</strong> and check the request mode is <code>submit</code>.</p><p><strong>The stage is right but you need one more step inside it</strong> — for example queue a job after save but before Mailchimp runs — register a <strong>custom workflow task</strong> in that stage, positioned before or after a built-in task.</p><p><strong>You need a new phase in the pipeline</strong> — for example a fraud score after screening but before save — register a <strong>custom workflow stage</strong>. Page vs complete is not a new stage.</p><p>If you are unsure, start with the smallest hook. The two lifecycle events cover the common page-step and finished-form cases. Element events are the broadest; stage and task events are the escape hatch for a named slot in the pipeline.</p><h2 id="when-you-are-ready-to-implement" tabindex="-1">When You Are Ready to Implement <a class="header-anchor" href="#when-you-are-ready-to-implement" aria-label="Permalink to &quot;When You Are Ready to Implement&quot;">​</a></h2><p>The <a href="/developers/submission-workflow">Submission Workflow</a> developer reference has:</p><ul><li>Default task names per stage</li><li>Workflow mode details</li><li>Copy-paste examples for stage events, custom tasks, and task results</li><li>The full list of registration and before/after events</li></ul><p>For full walkthroughs with module structure and copy-paste classes, see <a href="/guides/submissions-workflows/using-submission-workflow-events">Using submission workflow events</a>, <a href="/guides/submissions-workflows/adding-a-custom-workflow-task-from-scratch">Adding a custom workflow task from scratch</a>, and <a href="/guides/submissions-workflows/adding-a-custom-workflow-stage-from-scratch">Adding a custom workflow stage from scratch</a>.</p><p><a href="/developers/events/submission-events">Submission Events</a> documents every event payload if you need the full reference.</p>`,34)])])}const m=s(n,[["render",i]]);export{c as __pageData,m as default};
